const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'Developer Workforce & Compensation Trends'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Decorative accent bar at top
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06,
    fill: { color: theme.accent }
  });

  // Decorative geometric element - right side
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.2, y: 0.8, w: 2.5, h: 4.0,
    fill: { color: theme.secondary },
    transparency: 60
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.6, y: 1.2, w: 2.0, h: 3.2,
    fill: { color: theme.accent },
    transparency: 70
  });

  // Main title
  slide.addText("Developer Workforce &\nCompensation Trends", {
    x: 0.6, y: 1.0, w: 6.2, h: 2.0,
    fontSize: 42, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left",
    lineSpacingMultiple: 1.1
  });

  // Survey subtitle
  slide.addText("2024 Stack Overflow Survey", {
    x: 0.6, y: 3.1, w: 6.0, h: 0.5,
    fontSize: 22, fontFace: "Calibri",
    color: theme.accent, align: "left"
  });

  // Key stat
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 3.8, w: 5.4, h: 0.5,
    fill: { color: theme.secondary },
    transparency: 40
  });
  slide.addText("65,437 respondents  |  180+ countries", {
    x: 0.6, y: 3.8, w: 5.4, h: 0.5,
    fontSize: 16, fontFace: "Calibri",
    color: "FFFFFF", align: "center", valign: "middle"
  });

  // Source attribution
  slide.addText("Source: survey.stackoverflow.co/2024/work", {
    x: 0.6, y: 5.0, w: 5.0, h: 0.3,
    fontSize: 11, fontFace: "Calibri",
    color: theme.light, align: "left"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "03045e",
    secondary: "0077b6",
    accent: "00b4d8",
    light: "90e0ef",
    bg: "caf0f8"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

