function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("84% of Developers Are Working, but Full-Time Employment Dips in the U.S.", {
    x: 0.4, y: 0.3, w: 9.2, h: 0.7,
