    fill: { color: theme.accent }
  });

  // Global employment status bar chart
  slide.addChart(pres.charts.BAR, [{
    name: "Global (%)",
    labels: ["Full-time", "Freelance / Contract", "Student", "Other"],
    values: [69, 16.4, 13.2, 1.4]
