const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 4,
  title: 'Salary by Developer Type'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Senior Executives and Dev Advocates Top $124K+ Median Salary", {
    x: 0.4, y: 0.3, w: 9.2, h: 0.6,
    fontSize: 22, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left",
    fit: "shrink"
  });

  // Accent line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 0.95, w: 2.0, h: 0.04,
    fill: { color: theme.accent }
  });

  // Horizontal bar chart of median salary by developer type
  slide.addChart(pres.charts.BAR, [{
    name: "Median Salary (USD)",
    labels: [
      "Student",
      "Front-end",
      "Full-stack",
      "Product Manager",
      "Blockchain",
      "Cloud Infra Engineer",
      "SRE",
      "Dev Experience",
      "Manager",
      "Dev Advocate",
      "Senior Executive"
    ],
    values: [15466, 48787, 63333, 80000, 85925, 96666, 99099, 109483, 115999, 124203, 127388]
  }], {
    x: 0.3, y: 1.1, w: 6.5, h: 4.2,
    barDir: "bar",
    showTitle: false,
    showLegend: false,
    chartColors: [theme.secondary],
    catAxisLabelColor: theme.primary,
    catAxisLabelFontSize: 9,
    valAxisLabelColor: theme.primary,
    valAxisLabelFontSize: 8,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: theme.primary,
    dataLabelFontSize: 8,
    valAxisTitle: "Median Salary (USD)",
    valAxisTitleColor: theme.primary,
    valAxisTitleFontSize: 8,
    chartArea: { fill: { color: "FFFFFF" } }
  });

  // Right side - Key callouts
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.0, y: 1.2, w: 2.7, h: 1.3,
    fill: { color: "FFFFFF" }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.0, y: 1.2, w: 0.06, h: 1.3,
    fill: { color: theme.accent }
  });
  slide.addText("$127K", {
    x: 7.2, y: 1.25, w: 2.3, h: 0.5,
    fontSize: 24, fontFace: "Georgia",
    color: theme.secondary, bold: true
  });
  slide.addText("Senior Executive — highest median\nsalary across all developer types", {
    x: 7.2, y: 1.75, w: 2.3, h: 0.6,
    fontSize: 10, fontFace: "Calibri",
    color: theme.primary
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.0, y: 2.7, w: 2.7, h: 1.3,
    fill: { color: "FFFFFF" }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.0, y: 2.7, w: 0.06, h: 1.3,
    fill: { color: theme.secondary }
  });
  slide.addText("$99K", {
    x: 7.2, y: 2.75, w: 2.3, h: 0.5,
    fontSize: 24, fontFace: "Georgia",
    color: theme.secondary, bold: true
  });
  slide.addText("SRE — highest-paid purely\ntechnical role", {
    x: 7.2, y: 3.25, w: 2.3, h: 0.6,
    fontSize: 10, fontFace: "Calibri",
    color: theme.primary
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.0, y: 4.2, w: 2.7, h: 0.7,
    fill: { color: "FFFFFF" }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.0, y: 4.2, w: 0.06, h: 0.7,
    fill: { color: theme.light }
  });
  slide.addText("22,677 salary responses (34.7% response rate)", {
    x: 7.2, y: 4.2, w: 2.3, h: 0.7,
    fontSize: 9, fontFace: "Calibri",
    color: theme.primary, valign: "middle"
  });

  // Source note referencing figure_1
  slide.addText("Source: Stack Overflow Survey 2024  |  See figure_1.jpg", {
    x: 0.4, y: 5.15, w: 6.0, h: 0.25,
    fontSize: 8, fontFace: "Calibri",
    color: theme.secondary
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("4", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "03045e",
    secondary: "0077b6",
    accent: "00b4d8",
    light: "90e0ef",
    bg: "caf0f8"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-04-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

